async function retry(fn, times, delayMs) {
  let last
  for (let i = 0; i < times; i++) {
    try { return await fn(i) } catch (e) {
      last = e
      if (i < times - 1) await new Promise((r) => setTimeout(r, delayMs))
    }
  }
  throw last
}
